/**
 * Timezone-resilient Date Matching Logic
 * Handles multiple spreadsheet date boundaries (YYYY-MM-DD vs M/D/YYYY) 
 * to prevent pipeline drift across execution intervals.
 */
const rows = $input.all();
const options = { timeZone: "America/New_York", year: "numeric", month: "2-digit", day: "2-digit" };
const formatter = new Intl.DateTimeFormat("en-US", options);
const [{ value: month }, , { value: day }, , { value: year }] = formatter.formatToParts(new Date());

const targetDash = `${year}-${month}-${day}`;
const targetSlash = `${parseInt(month)}/${parseInt(day)}/${year}`;
const matchedPayloads = [];

for (const row of rows) {
    const data = row.json;
    if (!data.Date) continue;
    const rawDateStr = String(data.Date).trim();
    const isolatedDate = rawDateStr.split("T")[0];

    if (isolatedDate === targetDash || isolatedDate === targetSlash) {
        // Fallback checks for dynamic header labels
        const description = data["Special Description"] || data["Post Note"] || data.Description || data["Item Description"] || "";
        if (!description.trim()) continue;

        matchedPayloads.push({
            json: {
                matched_run: true,
                metadata: {
                    date: isolatedDate,
                    day: data.Day ? data.Day.trim() : "Special Day",
                    folder_timestamp: `${isolatedDate}_${data.Day ? data.Day.trim() : ""}`.trim()
                },
                content_payload: {
                    description: description.trim(),
                    offer: data.Offer || data["Promo Offer"] || data.Deal ? String(data.Offer || data["Promo Offer"] || data.Deal).trim() : "",
                    notes: data.Notes || data["Additional Notes"] ? String(data.Notes || data["Additional Notes"]).trim() : ""
                }
            }
        });
    }
}
return matchedPayloads;

/**
 * Defensive JSON Parser & Sanitization Node
 * Isolates the raw JSON structures from LLM markdown enclosures 
 * to avoid downstream runtime parse exceptions.
 */
const items = $input.all();
return items.map(item => {
    let inputData = item.json.text || item.json.output || "";
    let parsed;
    try {
        const jsonMatch = inputData.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
            parsed = JSON.parse(jsonMatch[0]);
        } else {
            throw new Error("No JSON object found.");
        }
    } catch (e) {
        // Robust structural fallback values to maintain pipeline availability
        parsed = {
            canva_assets: { dish_title: "Today's Feature", offer_badge: "Special Offer" },
            flux_prompt: "Professional close-up product photography, clean corporate staging on a modern rustic background, highly detailed, photorealistic.",
            captions: { instagram: "", facebook: "", tiktok: "", sms: "", trendy_touchy: "" }
        };
    }
    return {
        json: {
            dish_title: parsed.canva_assets ? parsed.canva_assets.dish_title : "Special Feature",
            offer_badge: parsed.canva_assets ? parsed.canva_assets.offer_badge : "Special Offer",
            image_prompt: parsed.flux_prompt || parsed.image_prompt,
            caption_instagram: parsed.captions ? parsed.captions.instagram : "",
            caption_facebook: parsed.captions ? parsed.captions.facebook : "",
            caption_tiktok: parsed.captions ? parsed.captions.tiktok : "",
            caption_sms: parsed.captions ? parsed.captions.sms : "",
            caption_trendy_touchy: parsed.captions ? parsed.captions.trendy_touchy : ""
        }
    };
});

/**
 * Serverless Dynamic Layout Compiler
 * Decouples raw business graphics from brittle static image-editor APIs.
 * Compiles customized HTML elements structured dynamically with CSS Flexbox & Grid.
 */

// 🔑 CONFIGURATION: ENTER YOUR BRAND DETAILS HERE
const USER_ID = "YOUR_HCTI_USER_ID";
const API_KEY = "YOUR_HCTI_API_KEY";

const BRAND_NAME = "YOUR BRAND NAME";
const ACCENT_COLOR = "#ff9900";
const TEXT_ACCENT_COLOR = "#000000";
const METADATA_LINE_1 = "📍 123 Main Street, New York, NY";
const METADATA_LINE_2 = "📞 (555) 019-9111  •  🌐 yourwebsite.com";

// ------------------------------------------

const fluxImage = $node["HTTP Request: Flux Generation"].json.output[0];
const contract = $node["Parse JSON Contract"].json;
const meta = $node["Filter Today's Row"].json.metadata;

const dateRaw = meta.date;
const dayStr = meta.day || "TODAY";

const formatDateStr = (rawDate) => {
  try {
    const parts = rawDate.split('-');
    if (parts.length === 3) {
      const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      return `${months[parseInt(parts[1]) - 1]} ${parseInt(parts[2])}, ${parts[0]}`;
    }
  } catch (e) {}
  return rawDate;
};

const dateFormatted = formatDateStr(dateRaw);
const dateAndDayLabel = `${dayStr.toUpperCase()} • ${dateFormatted.toUpperCase()}`;

// ==========================================
// 1. INSTAGRAM LAYOUT (1:1 - 1080x1080)
// ==========================================
const instagramHtml = `<div class='ad-card instagram' style='background-image: url("${fluxImage}");'>
  <div class='overlay-top'>
    <div class='brand-logo'>${BRAND_NAME}</div>
    <div class='date-badge'>${dateAndDayLabel}</div>
  </div>
  <div class='overlay-bottom'>
    <div class='offer-tag-row'>
      <span class='offer-badge'>${contract.offer_badge}</span>
    </div>
    <h1 class='dish-title'>${contract.dish_title}</h1>
    <p class='restaurant-metadata'>${METADATA_LINE_1}  •  ${METADATA_LINE_2}</p>
  </div>
</div>`;

const instagramCss = `@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&family=Poppins:wght@400;600;700&display=swap');
* { box-sizing: border-box; margin: 0; padding: 0; }
.ad-card { width: 1080px; height: 1080px; position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 60px; background-size: cover; background-position: center; font-family: 'Poppins', sans-serif; overflow: hidden; }
.ad-card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0) 25%, rgba(0,0,0,0) 65%, rgba(0,0,0,0.85) 100%); z-index: 1; }
.overlay-top { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; width: 100%; }
.brand-logo { font-family: 'Playfair Display', serif; font-size: 34px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; text-shadow: 2px 2px 8px rgba(0,0,0,0.6); border-bottom: 3px solid ${ACCENT_COLOR}; padding-bottom: 5px; }
.date-badge { background: rgba(0, 0, 0, 0.6); color: #ffffff; font-size: 14px; font-weight: 700; padding: 8px 16px; border-radius: 4px; border-left: 3px solid ${ACCENT_COLOR}; letter-spacing: 1px; }
.overlay-bottom { position: relative; z-index: 2; width: 100%; margin-top: auto; }
.offer-tag-row { margin-bottom: 12px; }
.offer-badge { background: ${ACCENT_COLOR}; color: ${TEXT_ACCENT_COLOR}; font-size: 18px; font-weight: 700; text-transform: uppercase; padding: 8px 18px; border-radius: 4px; box-shadow: 0 4px 10px rgba(0,0,0,0.3); letter-spacing: 1px; }
.dish-title { font-family: 'Playfair Display', serif; font-size: 72px; font-weight: 700; color: #ffffff; margin-bottom: 15px; text-shadow: 3px 3px 15px rgba(0,0,0,0.8); line-height: 1.1; font-style: italic; }
.restaurant-metadata { color: #e2e8f0; font-size: 16px; line-height: 1.4; text-shadow: 2px 2px 6px rgba(0,0,0,0.8); font-weight: 400; border-top: 1px solid rgba(255,255,255,0.2); padding-top: 15px; }`;

// ==========================================
// 2. FACEBOOK LAYOUT (1:1 - 1080x1080 community-centered)
// ==========================================
const facebookHtml = `<div class='ad-card facebook' style='background-image: url("${fluxImage}");'>
  <div class='overlay-top'>
    <div class='brand-logo'>${BRAND_NAME}</div>
    <div class='date-badge'>${dateAndDayLabel}</div>
  </div>
  <div class='overlay-bottom'>
    <h1 class='dish-title'>${contract.dish_title}</h1>
    <div class='fb-announcement'>
      <span class='badge-label'>TODAY'S SPECIAL OFFER</span>
      <p class='offer-desc'>${contract.offer_badge}</p>
    </div>
    <p class='restaurant-metadata'>${METADATA_LINE_1}<br>${METADATA_LINE_2}</p>
  </div>
</div>`;

const facebookCss = `@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&family=Poppins:wght@400;600;700&display=swap');
* { box-sizing: border-box; margin: 0; padding: 0; }
.ad-card { width: 1080px; height: 1080px; position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 60px; background-size: cover; background-position: center; font-family: 'Poppins', sans-serif; overflow: hidden; }
.ad-card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.1) 30%, rgba(0,0,0,0.1) 60%, rgba(0,0,0,0.9) 100%); z-index: 1; }
.overlay-top { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; width: 100%; }
.brand-logo { font-family: 'Playfair Display', serif; font-size: 34px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; text-shadow: 2px 2px 8px rgba(0,0,0,0.6); border-bottom: 3px solid ${ACCENT_COLOR}; padding-bottom: 5px; }
.date-badge { background: ${ACCENT_COLOR}; color: ${TEXT_ACCENT_COLOR}; font-size: 14px; font-weight: 700; padding: 8px 16px; border-radius: 4px; letter-spacing: 1px; box-shadow: 0 4px 8px rgba(0,0,0,0.2); }
.overlay-bottom { position: relative; z-index: 2; width: 100%; margin-top: auto; }
.dish-title { font-family: 'Playfair Display', serif; font-size: 68px; font-weight: 700; color: #ffffff; margin-bottom: 18px; text-shadow: 3px 3px 15px rgba(0,0,0,0.8); line-height: 1.1; }
.fb-announcement { background: rgba(0, 0, 0, 0.75); border-left: 5px solid ${ACCENT_COLOR}; padding: 15px 20px; border-radius: 4px; margin-bottom: 20px; }
.badge-label { color: ${ACCENT_COLOR}; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; display: block; margin-bottom: 4px; }
.offer-desc { color: #ffffff; font-size: 24px; font-weight: 700; text-transform: uppercase; }
.restaurant-metadata { color: #cbd5e1; font-size: 15px; line-height: 1.5; text-shadow: 2px 2px 6px rgba(0,0,0,0.8); font-weight: 400; border-top: 1px solid rgba(255,255,255,0.15); padding-top: 15px; }`;

// ==========================================
// 3. TIKTOK LAYOUT (9:16 - 1080x1920 Vertical format!)
// ==========================================
const tiktokHtml = `<div class='ad-card tiktok' style='background-image: url("${fluxImage}");'>
  <div class='overlay-top'>
    <div class='date-pill'>${dateAndDayLabel}</div>
    <div class='brand-logo-small'>${BRAND_NAME}</div>
  </div>
  <div class='overlay-bottom'>
    <div class='tiktok-badge-container'>
      <span class='tt-badge'>🔥 ${contract.offer_badge}</span>
    </div>
    <h1 class='dish-title-large'>${contract.dish_title}</h1>
    <div class='brand-footer'>
      <p class='brand-subtitle'>${METADATA_LINE_1}</p>
      <div class='brand-url'>${WEBSITE}</div>
    </div>
  </div>
</div>`;

const tiktokCss = `@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&family=Poppins:wght@400;600;700&display=swap');
* { box-sizing: border-box; margin: 0; padding: 0; }
.ad-card { width: 1080px; height: 1920px; position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 80px; background-size: cover; background-position: center; font-family: 'Poppins', sans-serif; overflow: hidden; }
.ad-card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, rgba(0,0,0,0) 20%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.9) 100%); z-index: 1; }
.overlay-top { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: flex-start; gap: 15px; width: 100%; }
.brand-logo-small { font-family: 'Playfair Display', serif; font-size: 28px; font-weight: 700; color: #ffffff; letter-spacing: 3px; text-transform: uppercase; text-shadow: 2px 2px 8px rgba(0,0,0,0.8); }
.date-pill { background: ${ACCENT_COLOR}; color: ${TEXT_ACCENT_COLOR}; font-size: 16px; font-weight: 700; padding: 10px 24px; border-radius: 50px; letter-spacing: 1.5px; box-shadow: 0 6px 12px rgba(0,0,0,0.3); }
.overlay-bottom { position: relative; z-index: 2; width: 100%; margin-top: auto; }
.tiktok-badge-container { margin-bottom: 25px; }
.tt-badge { background: #ffffff; color: #000000; font-size: 28px; font-weight: 700; text-transform: uppercase; padding: 14px 28px; border-radius: 8px; box-shadow: 0 10px 25px rgba(0,0,0,0.4); letter-spacing: 1px; display: inline-block; border-left: 6px solid ${ACCENT_COLOR}; }
.dish-title-large { font-family: 'Playfair Display', serif; font-size: 110px; font-weight: 700; color: #ffffff; margin-bottom: 25px; text-shadow: 4px 4px 20px rgba(0,0,0,0.95); line-height: 1.05; font-style: italic; }
.brand-footer { border-top: 2px solid rgba(255,255,255,0.2); padding-top: 25px; }
.brand-subtitle { color: #cbd5e1; font-size: 20px; text-shadow: 2px 2px 6px rgba(0,0,0,0.8); font-weight: 400; margin-bottom: 10px; }
.brand-url { color: ${ACCENT_COLOR}; font-size: 24px; font-weight: 700; text-transform: lowercase; letter-spacing: 1px; text-shadow: 2px 2px 6px rgba(0,0,0,0.8); }`;

// ==========================================
// Dynamic Authorization Token
// ==========================================
const token = Buffer.from(`${USER_ID}:${API_KEY}`).toString("base64");
const authorizationHeader = `Basic ${token}`;

return [
  {
    json: {
      serialized_body: JSON.stringify({
        html: instagramHtml,
        css: instagramCss,
        google_fonts: "Playfair Display|Poppins"
      }),
      auth_header: authorizationHeader,
      file_name: "instagram.png"
    }
  },
  {
    json: {
      serialized_body: JSON.stringify({
        html: facebookHtml,
        css: facebookCss,
        google_fonts: "Playfair Display|Poppins"
      }),
      auth_header: authorizationHeader,
      file_name: "fb.png"
    }
  },
  {
    json: {
      serialized_body: JSON.stringify({
        html: tiktokHtml,
        css: tiktokCss,
        google_fonts: "Playfair Display|Poppins"
      }),
      auth_header: authorizationHeader,
      file_name: "tiktok.png"
    }
  }
];

const items = $input.all();
return items.map(item => {
    const promptText = item.json.image_prompt || '';
    return {
        json: item.json,
        binary: {
            data: {
                data: Buffer.from(promptText, 'utf-8').toString('base64'),
                mimeType: 'text/plain',
                fileName: 'Prompt Used.txt'
            }
        }
    };
});
